package in.gaurav.bhavscanner;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.provider.OpenableColumns;import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import java.text.*;
public class MainActivity extends Activity {
 static final int PICK=51; SQLiteDatabase db; LinearLayout root,results; Spinner choices; TextView status; EditText find;
 String[] filters={"All alerts","Volume >50%","Price >5%","Both alerts","Consistent uptrend","Consistent downtrend"};
 static class Stock {String s,series,name,day;double price,prev,chg,vchg;long vol,oldVol;boolean hasVolume;int up,down;}
 public void onCreate(Bundle b){super.onCreate(b);db=openOrCreateDatabase("bhavcopy.db",0,null);db.execSQL("CREATE TABLE IF NOT EXISTS stocks(day TEXT,symbol TEXT,series TEXT,name TEXT,prev REAL,close REAL,vol INTEGER,PRIMARY KEY(day,symbol,series))");draw();}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setPadding(12,13,12,13);return t;}
 void button(String title,Runnable job){Button b=new Button(this);b.setText(title);b.setAllCaps(false);root.addView(b);b.setOnClickListener(v->job.run());}
 void draw(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(15,25,15,15);scroll.addView(root);setContentView(scroll);root.addView(text("NSE BHAVCOPY TREND SCANNER",23));root.addView(text("Developed By: Gaurav Kharva",13));status=text("",14);root.addView(status);
 button("Upload NSE PR ZIP or pd CSV",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,PICK);});
 choices=new Spinner(this);choices.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,filters));root.addView(choices);
 find=new EditText(this);find.setHint("Search NSE symbol");find.setSingleLine(true);root.addView(find);
 button("Scan stocks",this::scanView);button("Share CSV results",this::share);
 results=new LinearLayout(this);results.setOrientation(1);root.addView(results);
 choices.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> x){}public void onItemSelected(android.widget.AdapterView<?> x,View v,int i,long id){scanView();}});
 scanView();}
 List<String> dates(){List<String> d=new ArrayList<>();Cursor c=db.rawQuery("SELECT DISTINCT day FROM stocks ORDER BY day DESC LIMIT 30",null);while(c.moveToNext())d.add(c.getString(0));c.close();return d;}
 double pct(double n,double old){return old>0?(n/old-1)*100:Double.NaN;}
 List<Stock> compute(){List<String>d=dates();List<Stock> arr=new ArrayList<>();if(d.isEmpty())return arr;Cursor c=db.rawQuery("SELECT symbol,series,name,prev,close,vol FROM stocks WHERE day=?",new String[]{d.get(0)});
 while(c.moveToNext()){Stock s=new Stock();s.day=d.get(0);s.s=c.getString(0);s.series=c.getString(1);s.name=c.getString(2);s.prev=c.getDouble(3);s.price=c.getDouble(4);s.vol=c.getLong(5);s.chg=pct(s.price,s.prev);
 double newPrice=s.price;long newVol=s.vol;boolean upOk=true,downOk=true;
 for(int k=1;k<Math.min(5,d.size());k++){Cursor p=db.rawQuery("SELECT close,vol FROM stocks WHERE day=? AND symbol=? AND series=?",new String[]{d.get(k),s.s,s.series});if(!p.moveToFirst()){p.close();break;}double op=p.getDouble(0);long ov=p.getLong(1);p.close();
 if(k==1&&ov>0){s.hasVolume=true;s.oldVol=ov;s.vchg=pct(s.vol,ov);}
 if(upOk&&newPrice>op&&newVol>ov)s.up++;else upOk=false;
 if(downOk&&newPrice<op&&newVol>ov)s.down++;else downOk=false;
 if(!upOk&&!downOk)break;newPrice=op;newVol=ov;}
 arr.add(s);}c.close();return arr;}
 boolean match(Stock s,int f){boolean volume=s.hasVolume&&s.vchg>50,price=s.chg>5;switch(f){case 1:return volume;case 2:return price;case 3:return volume&&price;case 4:return s.up>=2;case 5:return s.down>=2;default:return volume||price||s.up>=2||s.down>=2;}}
 String percent(double n){return Double.isFinite(n)?String.format(Locale.US,"%+.2f%%",n):"N/A";}
 List<Stock> selected(){List<Stock> list=new ArrayList<>();int category=choices.getSelectedItemPosition();String query=find.getText().toString().trim().toUpperCase(Locale.US);for(Stock s:compute())if(match(s,category)&&(query.isEmpty()||s.s.toUpperCase(Locale.US).contains(query)))list.add(s);list.sort((a,b)->Double.compare(b.hasVolume?b.vchg:-9999,a.hasVolume?a.vchg:-9999));return list;}
 void scanView(){if(results==null)return;results.removeAllViews();List<String> d=dates();status.setText(d.isEmpty()?"Upload the first NSE daily ZIP.":"Latest session: "+d.get(0)+" • Saved days: "+d.size()+" / 30"+(d.size()<5?"\nUpload at least 5 trading days for fuller trend history.":""));List<Stock> list=selected();results.addView(text("Matching stocks: "+list.size(),18));if(d.size()==1)results.addView(text("Volume alerts require a previous trading day's ZIP.",13));int count=0;for(Stock s:list){if(count++>=250){results.addView(text("Showing first 250; search to narrow.",12));break;}String flags=(s.hasVolume&&s.vchg>50?" • VOLUME +50%":"")+(s.chg>5?" • PRICE +5%":"")+(s.up>=2?" • UP "+(s.up+1)+" days":"")+(s.down>=2?" • DOWN "+(s.down+1)+" days":"");
 results.addView(text(s.s+" ("+s.series+")"+flags+"\n"+s.name+"\nClose ₹"+s.price+" • Price "+percent(s.chg)+"\nVolume "+s.vol+" • Change "+(s.hasVolume?percent(s.vchg):"N/A"),14));}}
 @Override protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r!=PICK||code!=RESULT_OK||data==null)return;Uri uri=data.getData();new Thread(()->{try{int n=importFile(uri);runOnUiThread(()->{Toast.makeText(this,"Imported "+n+" records",Toast.LENGTH_LONG).show();draw();});}catch(Exception ex){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Import failed").setMessage(ex.getMessage()).setPositiveButton("OK",null).show());}}).start();}
 int importFile(Uri uri)throws Exception{String filename="";Cursor m=getContentResolver().query(uri,null,null,null,null);if(m!=null){if(m.moveToFirst()){int i=m.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0)filename=m.getString(i);}m.close();}
 try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("Cannot open file");if(filename.toLowerCase(Locale.US).endsWith(".zip")){try(ZipInputStream zip=new ZipInputStream(input)){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=new File(e.getName()).getName();if(name.matches("(?i)pd\\d{8}\\.csv"))return readCSV(new BufferedReader(new InputStreamReader(zip,StandardCharsets.UTF_8)),name);zip.closeEntry();}}throw new IOException("No pdDDMMYYYY.csv found in ZIP");}if(filename.matches("(?i)pd\\d{8}\\.csv"))return readCSV(new BufferedReader(new InputStreamReader(input,StandardCharsets.UTF_8)),filename);throw new IOException("Choose NSE PR ZIP or pdDDMMYYYY.csv");}}
 int readCSV(BufferedReader in,String name)throws Exception{java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)pd(\\d{2})(\\d{2})(\\d{4})\\.csv").matcher(name);if(!m.matches())throw new IOException("Invalid dated filename");String day=m.group(3)+"-"+m.group(2)+"-"+m.group(1);SimpleDateFormat fmt=new SimpleDateFormat("yyyy-MM-dd",Locale.US);fmt.setLenient(false);fmt.parse(day);
 String first=in.readLine();if(first==null)throw new IOException("Empty CSV");String[] fields=first.split(",",-1);Map<String,Integer> ix=new HashMap<>();for(int i=0;i<fields.length;i++)ix.put(fields[i].trim().toUpperCase(Locale.US).replace("\ufeff",""),i);
 String[] required={"MKT","SYMBOL","SERIES","SECURITY","PREV_CL_PR","CLOSE_PRICE","NET_TRDQTY"};for(String k:required)if(!ix.containsKey(k))throw new IOException("Missing NSE column "+k);
 int n=0;db.beginTransaction();try{db.delete("stocks","day=?",new String[]{day});String line;while((line=in.readLine())!=null){String[] a=line.split(",",-1);if(a.length<fields.length)continue;String market=a[ix.get("MKT")].trim(),symbol=a[ix.get("SYMBOL")].trim(),series=a[ix.get("SERIES")].trim();if(!market.equalsIgnoreCase("N")||symbol.isEmpty()||series.isEmpty())continue;
 ContentValues v=new ContentValues();v.put("day",day);v.put("symbol",symbol);v.put("series",series);v.put("name",a[ix.get("SECURITY")].trim());v.put("prev",num(a[ix.get("PREV_CL_PR")]));v.put("close",num(a[ix.get("CLOSE_PRICE")]));v.put("vol",(long)num(a[ix.get("NET_TRDQTY")]));db.insertWithOnConflict("stocks",null,v,SQLiteDatabase.CONFLICT_REPLACE);n++;}
 if(n==0)throw new IOException("No valid NSE market records found");db.execSQL("DELETE FROM stocks WHERE day NOT IN (SELECT DISTINCT day FROM stocks ORDER BY day DESC LIMIT 30)");db.setTransactionSuccessful();}finally{db.endTransaction();}return n;}
 double num(String s){try{return Double.parseDouble(s.trim().replace("\"",""));}catch(Exception e){return 0;}}
 void share(){StringBuilder csv=new StringBuilder("date,symbol,series,close,previous_close,price_percent,volume,previous_volume,volume_percent,up_days,down_days\n");for(Stock s:selected())csv.append(s.day).append(',').append(s.s).append(',').append(s.series).append(',').append(s.price).append(',').append(s.prev).append(',').append(s.chg).append(',').append(s.vol).append(',').append(s.hasVolume?s.oldVol:"").append(',').append(s.hasVolume?s.vchg:"").append(',').append(s.up+1).append(',').append(s.down+1).append('\n');Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/csv");i.putExtra(Intent.EXTRA_TEXT,csv.toString());startActivity(Intent.createChooser(i,"Export analysis"));}
 protected void onDestroy(){db.close();super.onDestroy();}
}